-- Promote 13 reviewed slang candidates to the dictionary (2026-09-10 morning review, operator approved).
-- Approved: 꼰대·플렉스·지리다 (carried over from 09-09) + 흙수저·헬조선·원영적 사고·마기꾼·이생망·
-- 삐끼삐끼·확찐자·자낳괴·댕댕이·마라탕후루 (collected overnight 09-10).
-- Each entry was cross-checked against 3-4 independent sources (see slang_candidates.sources).
-- Unsettled etymologies are stated as unsettled in origin: 꼰대 (dialect 꼰데기 vs French comte),
-- 자낳괴 (AfreecaTV joke lineage documented by a single source).
-- 꼰대 and 지리다 do appear in 표준국어대사전, but their current usage differs from the standard
-- gloss, so the operator approved promotion.
-- related_words entries with no dictionary row (금수저·커여워·띵곡) are dropped to avoid dead refs.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, aliases, likes, saves, translations) values
('444', '꼰대', 'Kkon-Dae', 'new-slang', '가르치려 드는 권위적인 윗사람', '{"de": "Eine autoritäre ältere Person, die ständig belehrt", "en": "A bossy older person who lectures everyone", "es": "Un mayor autoritario que sermonea a todos", "ja": "説教したがる権威的な年上", "vi": "Người lớn tuổi gia trưởng thích lên lớp"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Mein Teamleiter ist so ein Kkondae — die Firmenfeier zu schwänzen ist eine Staatsaffäre.", "es": "Mi jefe de equipo es un kkondae total: faltar a la cena de empresa es un drama.", "ja": "うちのチーム長ほんとに老害っぽい。飲み会休むと大事になる。", "vi": "Sếp nhóm mình đúng kiểu kkondae, nghỉ tiệc công ty là chuyện lớn.", "eng": "My team lead is such a kkondae — skipping the work dinner is a whole crisis.", "kor": "우리 팀장님 진짜 꼰대야, 회식 빠지면 큰일 나."}, {"de": "Klang ich gerade wie ein Kkondae? Sorry haha", "es": "¿Acabo de sonar a kkondae? Perdón jaja", "ja": "今、老害っぽいこと言った?ごめんw", "vi": "Nãy mình nói nghe kkondae quá hả? Xin lỗi hihi", "eng": "Did I just sound like a kkondae? Sorry lol", "kor": "나 지금 꼰대처럼 말했나? 미안 ㅋㅋ"}], "definition": "나이나 지위를 앞세워 자기 생각을 옳다고 밀어붙이고 남을 가르치려 드는 사람. 원래 학생들이 선생님이나 나이 든 사람을 부르던 은어였는데, 2010년대 들어 직장 상사나 어른 전반으로 넓어졌다. 나이와 상관없이 태도가 그러면 「젊꼰(젊은 꼰대)」이라고 한다.", "definition_i18n": {"de": "Jemand, der Alter oder Rang benutzt, um die eigene Meinung durchzudrücken und andere zu belehren. Ursprünglich Schülerslang für Lehrer und alte Männer, in den 2010ern ausgeweitet auf Vorgesetzte und Erwachsene allgemein. Zeigt eine junge Person diese Haltung, heißt sie 젊꼰, ein „junger Kkondae“.", "en": "Someone who uses age or rank to insist their view is right and to lecture others. It began as student slang for teachers and old men, then broadened in the 2010s to cover bosses and grown-ups in general. When the attitude shows up in a young person, they get called 젊꼰, a “young kkondae.”", "es": "Alguien que se ampara en la edad o el cargo para imponer su criterio y sermonear a los demás. Empezó como jerga estudiantil para profesores y viejos, y en los 2010 se amplió a jefes y adultos en general. Si la actitud aparece en alguien joven, se le llama 젊꼰, un “kkondae joven”.", "ja": "年齢や地位を盾に自分の考えを正しいと押し通し、人を説教したがる人。もとは学生が先生や年配者を指す隠語だったが、2010年代に職場の上司や大人全般へ意味が広がった。年齢に関係なく態度がそうなら「チョルコン(若い老害)」と呼ぶ。", "vi": "Người lấy tuổi tác hay chức vụ ra để áp đặt ý mình và lên lớp người khác. Ban đầu là tiếng lóng học sinh gọi thầy cô và người già, tới thập niên 2010 mở rộng sang sếp và người lớn nói chung. Nếu thái độ đó xuất hiện ở người trẻ thì gọi là 젊꼰 — “kkondae trẻ”."}}]'::jsonb, '어원은 확정되지 않았고 크게 두 설이 있다. ①번데기의 영남 사투리 「꼰데기」에서 왔다는 방언설(주름 많은 늙은이라는 뜻). ②프랑스어로 백작을 뜻하는 「콩테(comte)」를 일제강점기에 작위를 받은 친일파가 자칭하던 것이 변했다는 설. 표준국어대사전에는 「늙은이」·「선생님」을 뜻하는 은어로 올라 있고, 2012년 무렵부터 「꼰대질」·「꼰대스럽다」 같은 파생어가 생기며 지금의 뜻으로 굳었다.', '{"de": "Die Herkunft ist ungeklärt; zwei Theorien dominieren. (1) Von kkondegi, dem Gyeongsang-Dialektwort für Seidenraupenpuppe — ein runzliger Alter. (2) Vom französischen comte (Graf), mit dem sich japanfreundliche Koreaner mit Adelstiteln in der Kolonialzeit angeblich selbst bezeichneten. Das Standardwörterbuch führt es als Slang für „alter Mann“ oder „Lehrer“; um 2012 kamen Ableitungen wie 꼰대질 auf und festigten die heutige Bedeutung.", "en": "The etymology is unsettled; two theories dominate. (1) From kkondegi, the Gyeongsang dialect word for a silkworm pupa — i.e. a wrinkled old person. (2) From the French comte (count), which pro-Japanese Koreans given noble titles under colonial rule supposedly used for themselves. The standard dictionary lists it as slang for “old man” or “teacher”; derivatives like 꼰대질 appeared around 2012 and locked in today''s meaning.", "es": "La etimología no está fijada; hay dos teorías principales. (1) De kkondegi, palabra dialectal de Gyeongsang para la crisálida: un viejo lleno de arrugas. (2) Del francés comte (conde), que se atribuían los coreanos pro-japoneses ennoblecidos durante la colonia. El diccionario estándar lo recoge como jerga para “viejo” o “profesor”; hacia 2012 surgieron derivados como 꼰대질 y fijaron el sentido actual.", "ja": "語源は未確定で、大きく二説ある。①さなぎを指す慶尚道方言「コンデギ」由来説(しわだらけの老人の意)。②フランス語で伯爵を意味する「コンテ」を、日本統治期に爵位を受けた親日派が自称したことに由来する説。標準国語大辞典には「老人」「先生」を指す隠語として載る。2012年ごろから「コンデ質」などの派生語が生まれ、現在の意味が定着した。", "vi": "Từ nguyên chưa được xác định, có hai giả thuyết chính. (1) Từ kkondegi, tiếng địa phương Gyeongsang chỉ con nhộng — ý chỉ ông già nhăn nheo. (2) Từ tiếng Pháp comte (bá tước), được cho là cách tự xưng của những người Hàn thân Nhật được phong tước thời thuộc địa. Từ điển chuẩn ghi nhận nó là tiếng lóng chỉ “ông già”, “thầy giáo”; khoảng 2012 xuất hiện các từ phái sinh như 꼰대질 và định hình nghĩa hiện nay."}'::jsonb, '본인에게 쓰면 자조 농담이 되고, 남에게 쓰면 꽤 센 비판이다. 당사자 앞에서 직접 부르는 말은 아니고 뒤에서 하거나 농담조로 쓴다. 나이와 무관하게 태도만 보고 붙이기도 한다(젊꼰).', '{"de": "Auf sich selbst gemünzt ein selbstironischer Scherz, auf andere gemünzt ziemlich scharfe Kritik. Man sagt es niemandem ins Gesicht, sondern hinter dem Rücken oder im Spaß. Es kann unabhängig vom Alter allein wegen der Haltung vergeben werden (젊꼰).", "en": "Said of yourself it''s a self-deprecating joke; said of someone else it''s a fairly sharp criticism. You don''t call someone this to their face — it''s used behind their back or jokingly. It can attach to anyone regardless of age, based on attitude alone (젊꼰).", "es": "Sobre uno mismo es una broma autocrítica; sobre otro es una crítica bastante dura. No se le dice a la cara: se usa a sus espaldas o en tono de broma. Puede aplicarse a cualquiera sin importar la edad, solo por la actitud (젊꼰).", "ja": "自分に使えば自虐的な冗談、他人に使えばかなり強い批判になる。面と向かって呼ぶ言葉ではなく、陰でか冗談まじりで使う。年齢に関係なく態度だけで付けることもある(チョルコン)。", "vi": "Nói về mình thì là đùa tự giễu; nói về người khác thì là lời chê khá nặng. Không nói thẳng vào mặt ai, mà nói sau lưng hoặc nói đùa. Có thể gán cho bất kỳ ai bất kể tuổi tác, chỉ dựa vào thái độ (젊꼰)."}'::jsonb, array['틀딱','나일리지','진지충'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Bossy old-school lecturer"}, {"lang": "🇯🇵 JA", "text": "説教好きの老害"}, {"lang": "🇨🇳 ZH", "text": "爱说教的老古董"}, {"lang": "🇻🇳 VI", "text": "Người thích lên lớp kiểu gia trưởng"}, {"lang": "🇪🇸 ES", "text": "Carroza que sermonea"}, {"lang": "🇩🇪 DE", "text": "Belehrender Besserwisser"}]'::jsonb),
('445', '플렉스', 'Peul-Rek-Seu', 'new-slang', '돈이나 능력을 대놓고 과시하기', '{"de": "Geld oder Status bewusst zur Schau stellen", "en": "Flaunting money or status on purpose", "es": "Presumir abiertamente de dinero o logros", "ja": "お金や実力を堂々と見せびらかすこと", "vi": "Khoe tiền hay đẳng cấp một cách công khai"}'::jsonb, null, '[{"type": "명사·동사", "examples": [{"de": "Gehalt kam rein, also hab ich ein bisschen geflext — neue Ohrhörer gekauft.", "es": "Me llegó el sueldo y me di un flex: me compré auriculares nuevos.", "ja": "給料入ったからちょっとフレックスした。イヤホン新しく買った。", "vi": "Có lương nên flex xíu, mua tai nghe mới rồi.", "eng": "Payday hit so I flexed a little — got myself new earbuds.", "kor": "월급 들어와서 플렉스 좀 했어. 이어폰 새로 삼."}, {"de": "Wenn du so weiterflext, hungerst du am Monatsende.", "es": "Como sigas haciendo flex así, a fin de mes te mueres de hambre.", "ja": "そんなにフレックスしてたら月末に飢えるよ。", "vi": "Cứ flex kiểu đó thì cuối tháng nhịn đói đó.", "eng": "Keep flexing like that and you''ll be starving by the end of the month.", "kor": "그렇게 플렉스하다가 월말에 굶는다."}], "definition": "비싼 물건을 사거나 성취를 자랑스럽게 드러내는 것. 영어 힙합 속어 flex에서 왔다. 요즘은 진짜 부자가 아니어도 「오늘 좀 플렉스했다」처럼 평소보다 큰 지출을 농담조로 가리키는 데 더 많이 쓴다.", "definition_i18n": {"de": "Etwas Teures kaufen oder eine Errungenschaft stolz zeigen. Es kommt vom englischen Hip-Hop-Slang flex. Heute benutzen es weniger die wirklich Reichen als vielmehr alle, die scherzhaft über eine größere Ausgabe als sonst reden — „heute hab ich mal geflext“.", "en": "Buying something expensive, or showing off an achievement with pride. It comes from the English hip-hop slang flex. These days it''s used less by the actually rich and more as a joke about spending more than usual — “I flexed a bit today.”", "es": "Comprarse algo caro o exhibir un logro con orgullo. Viene del argot hip-hop inglés flex. Hoy lo usan menos los ricos de verdad y más quien bromea sobre haber gastado más de lo habitual: “hoy me di un flex”.", "ja": "高い物を買ったり、成果を誇らしげに見せたりすること。英語のヒップホップ俗語flexから来た。最近は本当の富裕層でなくても「今日ちょっとフレックスした」のように、普段より大きな出費を冗談めかして指す使い方の方が多い。", "vi": "Mua đồ đắt tiền hoặc phô ra thành tựu một cách tự hào. Từ tiếng lóng hip-hop tiếng Anh flex. Ngày nay nó ít được dùng bởi người giàu thật mà chủ yếu để đùa về việc tiêu nhiều hơn thường lệ — “hôm nay flex xíu”."}}]'::jsonb, '1990년대 미국 힙합에서 「부나 물건을 과시하다」라는 속어로 쓰이던 flex가 원말이다. 한국에서는 2019년 래퍼 염따가 인스타그램과 Mnet 「쇼미더머니 8」에서 「플렉스 해버렸지 뭐야」라고 쓴 것이 결정적이었고, 기리보이 등 다른 래퍼들이 이어 쓰면서 음악을 넘어 소비 트렌드 용어로 퍼졌다.', '{"de": "Ursprung ist der US-Hip-Hop-Slang der 1990er, flex, „mit Reichtum oder Besitz protzen“. In Korea war 2019 der entscheidende Moment, als Rapper Yumdda auf Instagram und bei Mnets Show Me the Money 8 sagte: „Hab halt geflext.“ Andere Rapper wie Giriboy griffen es auf, und der Begriff verließ die Musik und wurde zum Konsumtrend-Vokabular.", "en": "The source is 1990s American hip-hop slang flex, “to show off wealth or possessions.” In Korea the decisive moment was 2019, when rapper Yumdda used the line “I went and flexed” on Instagram and on Mnet''s Show Me the Money 8; other rappers such as Giriboy picked it up, and it spread past music into consumer-trend vocabulary.", "es": "Viene del argot del hip-hop estadounidense de los noventa, flex, “presumir de riqueza o de posesiones”. En Corea el momento clave fue 2019, cuando el rapero Yumdda soltó “pues me hice un flex” en Instagram y en Show Me the Money 8 de Mnet; otros raperos como Giriboy lo retomaron y el término saltó de la música al vocabulario del consumo.", "ja": "元は1990年代のアメリカのヒップホップで「富や持ち物を見せびらかす」意味で使われたflex。韓国では2019年、ラッパーのヨムタがインスタグラムとMnet「ショー・ミー・ザ・マネー8」で「フレックスしちゃったんだよね」と使ったのが決定打で、キリボイら他のラッパーも続き、音楽を超えて消費トレンド語として広まった。", "vi": "Gốc là tiếng lóng hip-hop Mỹ thập niên 1990, flex, nghĩa “khoe của cải, đồ đạc”. Ở Hàn, bước ngoặt là năm 2019 khi rapper Yumdda nói “trót flex mất rồi” trên Instagram và trong Show Me the Money 8 của Mnet; các rapper khác như Giriboy dùng theo, và từ này vượt khỏi âm nhạc thành từ khóa của xu hướng tiêu dùng."}'::jsonb, '「플렉스하다」로 동사처럼 쓴다. 자기 소비를 가리킬 땐 자랑 반 농담 반이고, 남에게 「플렉스 심하다」라고 하면 과시가 지나치다는 지적이 된다. 액수가 크지 않아도 「나한테는 큰 지출」이면 붙일 수 있다.', '{"de": "Wird verbal als 플렉스하다 gebraucht. Über die eigenen Ausgaben halb Angeberei, halb Scherz; über andere (플렉스 심하다) ein Seitenhieb wegen zu viel Protzerei. Die Summe muss nicht groß sein — „groß für mich“ genügt.", "en": "Used verbally as 플렉스하다. About your own spending it''s half brag, half joke; said of someone else (플렉스 심하다) it''s a jab at showing off too much. The amount doesn''t have to be large — “big for me” is enough.", "es": "Se usa como verbo: 플렉스하다. Sobre el propio gasto es mitad alarde, mitad broma; dicho de otro (플렉스 심하다) es un reproche por presumir demasiado. No hace falta que la cifra sea alta: basta con que sea “mucho para mí”.", "ja": "「フレックスする」と動詞のように使う。自分の消費を指すときは自慢半分・冗談半分で、他人に「フレックスが激しい」と言えば見せびらかしすぎだという指摘になる。金額が大きくなくても「自分にとっては大きな出費」なら使える。", "vi": "Dùng như động từ: 플렉스하다. Nói về chi tiêu của mình thì nửa khoe nửa đùa; nói về người khác (플렉스 심하다) là chê khoe khoang quá. Số tiền không cần lớn — chỉ cần “lớn với mình” là được."}'::jsonb, array['갓생','인생샷','가성비'], array['flex'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Flex (show off wealth)"}, {"lang": "🇯🇵 JA", "text": "フレックス(散財自慢)"}, {"lang": "🇨🇳 ZH", "text": "炫富"}, {"lang": "🇻🇳 VI", "text": "Flex, khoe của"}, {"lang": "🇪🇸 ES", "text": "Flexear, presumir"}, {"lang": "🇩🇪 DE", "text": "Flexen, protzen"}]'::jsonb),
('446', '지리다', 'Ji-Ri-Da', 'new-slang', '너무 대단해서 감탄이 나온다', '{"de": "So krass, dass es dich umhaut", "en": "So amazing it knocks you sideways", "es": "Tan brutal que te deja sin palabras", "ja": "すごすぎて感嘆が出る", "vi": "Đỉnh tới mức phải thốt lên"}'::jsonb, null, '[{"type": "형용사·동사", "examples": [{"de": "Hast du das letzte Tor gesehen? Echt der Wahnsinn.", "es": "¿Viste el último gol? Brutal, de verdad.", "ja": "最後のゴール見た?マジでやばい。", "vi": "Xem bàn cuối chưa? Đỉnh thật sự.", "eng": "Did you see that last goal? Absolutely insane.", "kor": "마지막 골 봤어? 진짜 지린다."}, {"de": "Der Titeltrack des Albums hat echt abgeliefert.", "es": "El tema principal de este álbum se salió de verdad.", "ja": "今回のアルバムのタイトル曲、マジで神ってた。", "vi": "Ca khúc chủ đề album lần này đỉnh thật luôn.", "eng": "The title track on this album absolutely went off.", "kor": "이번 앨범 타이틀곡 지렸다 진짜."}], "definition": "원래 뜻은 「오줌을 조금 싸다」로 국어사전에 실린 표준어지만, 인터넷에서는 「지릴 정도로 대단하다」는 강조 감탄으로 쓴다. 「지린다」·「지렸다」 형태가 가장 흔하다. 실제 생리 현상을 말하는 게 아니라 놀람의 크기를 과장하는 표현이다.", "definition_i18n": {"de": "Die Wörterbuchbedeutung ist „sich ein wenig einnässen“ — es ist Standardkoreanisch, keine Neuschöpfung. Online dient es als Verstärker: „so krass, dass du dich einnässt“. Üblich sind die Formen 지린다 und 지렸다. Niemand meint die Körperfunktion; es ist reine Übertreibung dafür, wie geplättet man ist.", "en": "Its dictionary sense is “to wet yourself a little” — it''s standard Korean, not a coinage. Online it works as an intensifier: “so amazing you''d wet yourself.” The usual forms are 지린다 and 지렸다. Nobody means the bodily function; it''s pure hyperbole for how stunned you are.", "es": "Su sentido de diccionario es “orinarse un poco”: es coreano estándar, no un neologismo. En internet funciona como intensificador: “tan brutal que te meas”. Las formas habituales son 지린다 y 지렸다. Nadie se refiere a la función corporal; es pura hipérbole por lo impactado que estás.", "ja": "元の意味は「小便を少し漏らす」で、国語辞典に載る標準語。ネットでは「漏らすほどすごい」という強調の感嘆として使う。「지린다」「지렸다」の形が最も多い。実際の生理現象を言っているのではなく、驚きの大きさを盛る表現。", "vi": "Nghĩa từ điển là “tè ra một chút” — đây là tiếng Hàn chuẩn, không phải từ mới. Trên mạng nó thành từ nhấn mạnh: “đỉnh tới mức tè ra quần”. Dạng hay dùng là 지린다 và 지렸다. Không ai nói về chuyện sinh lý cả; đó chỉ là lối phóng đại mức độ choáng."}}]'::jsonb, '「지리다」 자체는 신조어가 아니라 「똥·오줌을 참지 못하고 조금 싸다」라는 뜻으로 표준국어대사전에 올라 있는 말이다. 인터넷에서 「너무 놀라 지릴 뻔했다」는 과장이 줄어들어 감탄사처럼 굳었다. 남성 위주 커뮤니티와 게임 채팅에서 먼저 퍼졌다는 설명이 일반적이지만 최초 사용 시점은 특정되지 않는다. 같은 방식으로 굳은 「오지다」와 짝처럼 쓰인다.', '{"de": "지리다 ist selbst keine Neuschöpfung — das Standardwörterbuch führt es als „sich ein wenig einnässen“. Online schrumpfte die Übertreibung „ich hätte mich fast eingenässt, so krass war das“ zu einem bloßen Ausruf. Meist heißt es, es habe sich zuerst über männerdominierte Foren und Game-Chats verbreitet, doch der früheste Beleg ist ungeklärt. Es bildet ein Paar mit 오지다, das auf demselben Weg entstand.", "en": "지리다 isn''t itself a coinage — the standard Korean dictionary lists it as “to wet yourself a little.” Online, the hyperbole “I nearly wet myself, it was that shocking” got compressed into a bare exclamation. It''s usually described as spreading first through male-dominated communities and game chat, but the earliest use isn''t pinned down. It pairs with 오지다, which hardened the same way.", "es": "지리다 no es en sí un neologismo: el diccionario estándar lo recoge como “orinarse un poco”. En internet, la hipérbole “casi me lo hago encima de la impresión” se comprimió hasta quedar como pura exclamación. Suele decirse que se extendió primero por foros mayoritariamente masculinos y chats de juegos, pero el primer uso no está fijado. Se usa en pareja con 오지다, endurecido por la misma vía.", "ja": "「지리다」自体は新造語ではなく、「大小便を我慢できず少し漏らす」という意味で標準国語大辞典に載っている語。ネット上で「驚きすぎて漏らしそうだった」という誇張が縮まり、感嘆詞のように定着した。男性中心のコミュニティやゲームチャットで先に広まったという説明が一般的だが、最初の使用時期は特定されていない。同じ経緯で定着した「오지다」と対で使われる。", "vi": "Bản thân 지리다 không phải từ mới — từ điển chuẩn ghi nghĩa “tè ra một chút”. Trên mạng, lối nói phóng đại “sốc tới suýt tè ra quần” bị rút gọn thành một thán từ. Người ta thường nói nó lan trước ở các cộng đồng đông nam giới và chat game, nhưng thời điểm dùng đầu tiên chưa xác định. Nó đi cặp với 오지다, vốn hình thành theo cùng cách."}'::jsonb, '비속어 성향이 있어 친구 사이나 온라인에서만 쓴다. 원뜻이 배설이라 어른·상사·처음 보는 사람 앞에서는 피한다. 칭찬으로만 쓰고, 사람의 인격을 두고 쓰지는 않는다.', '{"de": "Es hat einen derben Beiklang — also nur unter Freunden und online. Da die wörtliche Bedeutung Einnässen ist, vermeide es vor Älteren, Vorgesetzten oder Fremden. Es dient nur als Lob, nie zur Beurteilung des Charakters.", "en": "It has a crude edge, so keep it to friends and online. Since the literal sense is about wetting yourself, avoid it in front of elders, bosses or people you''ve just met. It''s used only as praise, never about someone''s character.", "es": "Tiene un punto vulgar, así que resérvalo para amigos y para internet. Como el sentido literal es orinarse, evítalo ante mayores, jefes o desconocidos. Solo se usa como elogio, nunca sobre el carácter de alguien.", "ja": "俗語的な語感があるので友人同士やオンラインでのみ使う。元の意味が排泄なので、目上・上司・初対面の人の前では避ける。褒め言葉としてのみ使い、人の人格について言うことはない。", "vi": "Nó hơi thô nên chỉ dùng với bạn bè và trên mạng. Vì nghĩa đen là tè ra quần, tránh dùng trước người lớn, cấp trên hay người mới gặp. Chỉ dùng để khen, không bao giờ nói về nhân cách ai đó."}'::jsonb, array['오지다','쩐다','개미쳤다'], array['지린다','지렸다'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Insane / mind-blowing"}, {"lang": "🇯🇵 JA", "text": "やばい(すごい)"}, {"lang": "🇨🇳 ZH", "text": "太牛了"}, {"lang": "🇻🇳 VI", "text": "Đỉnh của chóp"}, {"lang": "🇪🇸 ES", "text": "Brutal"}, {"lang": "🇩🇪 DE", "text": "Der Wahnsinn"}]'::jsonb),
('447', '원영적 사고', 'Won-Yeong-Jeok Sa-Go', 'new-slang', '나쁜 일도 결국 나한테 좋은 일이라 믿는 초긍정 사고', '{"de": "Ultrapositives Denken, das jeden Rückschlag in Glück verwandelt", "en": "Ultra-positive thinking that spins any setback into luck", "es": "Pensamiento ultrapositivo que convierte cualquier revés en suerte", "ja": "悪いことも結局は自分の幸運だと考える超ポジティブ思考", "vi": "Lối nghĩ siêu tích cực, biến mọi rủi ro thành may mắn"}'::jsonb, '[워녕적 사고]', '[{"type": "명사", "examples": [{"de": "Bus verpasst, dafür Platz ganz vorne. Voll das Wonyoung-Denken, oder?", "es": "Perdí el bus pero por eso me tocó asiento delantero. Puro pensamiento Wonyoung, ¿no?", "ja": "バス逃したけどおかげで前の席座れた。完全にウォニョン的思考でしょ?", "vi": "Lỡ xe buýt mà nhờ vậy được ngồi ghế đầu. Đúng kiểu nghĩ Wonyoung luôn ha?", "eng": "I missed my bus but ended up with a front seat — total Wonyoung thinking, right?", "kor": "버스 놓쳤는데 그 덕에 앞자리 앉았어. 완전 원영적 사고지?"}, {"de": "Prüfung verhauen, aber beim Wiederholen lerne ich es besser~ Wonyoung-Denken aktiviert.", "es": "Suspendí, pero repetirla me hará aprender mejor~ activando pensamiento Wonyoung.", "ja": "試験ダメだったけど再履修したらもっと学べるでしょ〜ウォニョン的思考発動中。", "vi": "Thi tạch nhưng học lại thì hiểu kỹ hơn~ đang bật chế độ nghĩ Wonyoung.", "eng": "Bombed the exam, but retaking it means I''ll learn it better — casting Wonyoung thinking.", "kor": "시험 망했는데 재수강하면 더 잘 배우겠지~ 원영적 사고 시전 중."}], "definition": "아이브 장원영의 말투에서 나온 말로, 안 좋은 상황도 ''결국 나한테 이득''이라고 해석하는 극단적 긍정 사고. ''오히려 좋아''의 2020년대판이며 파생어 ''럭키비키''와 세트로 쓰인다.", "definition_i18n": {"de": "Benannt nach Jang Won-young (IVE): selbst Schlechtes als ''am Ende ein Gewinn für mich'' deuten — die 2020er-Version von 오히려 좋아, meist zusammen mit dem Ableger 럭키비키.", "en": "Named after IVE''s Jang Won-young, it means reading even a bad situation as ''lucky for me in the end'' — the 2020s version of 오히려 좋아, usually paired with its spin-off 럭키비키.", "es": "Bautizado por Jang Won-young (IVE), describe leer hasta lo malo como ''al final me conviene'': la versión 2020 de 오히려 좋아, y suele ir con su derivado 럭키비키.", "ja": "IVEのチャン・ウォニョンの話し方から生まれた語で、悪い状況も「結局は自分の得」と解釈する極端なポジティブ思考。「オヒロ・チョア」の2020年代版で、派生語「ラッキービッキー」とセットで使う。", "vi": "Đặt theo Jang Won-young (IVE), chỉ cách nghĩ rằng cả chuyện xui cũng ''rốt cuộc có lợi cho mình'' — phiên bản 2020 của 오히려 좋아, thường đi kèm biến thể 럭키비키."}}]'::jsonb, '2024년 3월, 아이브 장원영이 브이로그에서 ''앞사람이 빵을 다 사가서 오히려 갓 나온 빵을 받게 됐다, 역시 행운의 여신은 내 편''이라고 말한 것을 한 팬이 ''원영적 사고''라 이름 붙이며 시작됐다. 같은 달 팬 계정의 패러디 게시글이 SNS로 퍼지면서 대중화됐다.', '{"de": "Im März 2024 erzählte Jang Won-young (IVE) im Vlog, sie habe frisches Brot bekommen, weil die Person vor ihr alles gekauft hatte — ''die Glücksgöttin ist auf meiner Seite''. Ein Fan nannte das 원영적 사고; eine Fan-Parodie im selben Monat machte es viral.", "en": "In March 2024 IVE''s Jang Won-young said in a vlog that because the person ahead bought all the bread, she got a fresher batch — ''the goddess of luck is on my side.'' A fan labelled this 원영적 사고, and a parody fan post that month spread it across social media.", "es": "En marzo de 2024, Jang Won-young (IVE) contó en un vlog que, como la persona de delante compró todo el pan, a ella le tocó recién horneado: ''la diosa de la suerte está de mi lado''. Una fan lo llamó 원영적 사고 y una parodia viral ese mes lo popularizó.", "ja": "2024年3月、IVEのチャン・ウォニョンがVlogで「前の人がパンを全部買ったおかげで焼きたてをもらえた、やっぱり幸運の女神は私の味方」と語り、ファンがこれを「ウォニョン的思考」と名付けた。同月のファン投稿のパロディがSNSで拡散し定着。", "vi": "Tháng 3/2024, Jang Won-young (IVE) kể trong vlog rằng người phía trước mua hết bánh nên cô được ổ mới ra lò — ''nữ thần may mắn đứng về phía tôi''. Một fan gọi đó là 원영적 사고, và bài chế của fan tháng đó lan khắp mạng xã hội."}'::jsonb, '실패나 불운을 웃어넘길 때 ''이거 완전 원영적 사고''처럼 쓴다. 자기 위안이자 유머지만, 억지스러울 땐 정신승리를 놀리는 뉘앙스도 된다.', '{"de": "Man lacht damit über Pech oder Misserfolg: ''voll das Wonyoung-Denken''. Selbsttrost und Scherz zugleich — wenn es zu weit hergeholt ist, spottet es über Schönreden.", "en": "Used to laugh off a failure or bit of bad luck — ''that''s peak Wonyoung thinking.'' It''s self-comfort and a joke, but when it''s a stretch it can tease someone for coping too hard.", "es": "Se usa para reírse de un fallo o mala suerte: ''esto es puro pensamiento Wonyoung''. Es autoconsuelo y broma, pero si es forzado se burla de quien se engaña.", "ja": "失敗や不運を笑い飛ばすときに「これ完全にウォニョン的思考」のように使う。自己慰めでありユーモアだが、無理があると精神勝利をからかう含みにもなる。", "vi": "Dùng khi cười trừ chuyện thất bại hay xui xẻo: ''đúng kiểu nghĩ Wonyoung''. Vừa tự an ủi vừa đùa, nhưng nếu gượng ép thì thành trêu ai đó đang tự huyễn."}'::jsonb, array['럭키비키','오히려 좋아','갓생'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Wonyoung thinking / relentless silver-lining mindset"}, {"lang": "🇯🇵 JA", "text": "ウォニョン的思考(超ポジティブ思考)"}, {"lang": "🇨🇳 ZH", "text": "元英式思维(超级正能量思考)"}, {"lang": "🇻🇳 VI", "text": "Lối nghĩ Wonyoung (siêu tích cực)"}, {"lang": "🇪🇸 ES", "text": "Pensamiento Wonyoung (ultrapositivo)"}, {"lang": "🇩🇪 DE", "text": "Wonyoung-Denken (ultrapositiv)"}]'::jsonb),
('448', '헬조선', 'Hel-Jo-Seon', 'new-slang', '살기 힘든 한국 사회를 지옥에 빗대 자조하는 말', '{"de": "Selbstironischer Spitzname für Korea als ''Hölle''", "en": "A self-deprecating nickname for Korea as a ''hell'' to live in", "es": "Apodo autocrítico de Corea como un ''infierno'' donde vivir", "ja": "生きづらい韓国社会を地獄になぞらえた自嘲語", "vi": "Cách gọi tự giễu Hàn Quốc như ''địa ngục'' để sống"}'::jsonb, '[헬쪼선]', '[{"type": "명사", "examples": [{"de": "Miete steigt, Gehalt bleibt … echt Hell Joseon.", "es": "Sube el alquiler y el sueldo igual… esto es Hell Joseon de verdad.", "ja": "家賃は上がるのに給料はそのまま…まさにヘル朝鮮。", "vi": "Tiền trọ tăng mà lương y nguyên… đúng là Hell Joseon.", "eng": "Rent goes up, my paycheck doesn''t — this really is Hell Joseon.", "kor": "월세는 오르고 월급은 그대로고… 진짜 헬조선이다."}, {"de": "100 Bewerber auf einen Platz. Jetzt verstehe ich das mit Hell Joseon.", "es": "La convocatoria es 100 a 1. Ya entiendo lo de Hell Joseon.", "ja": "公募100倍だって。ヘル朝鮮って言われる理由がわかる。", "vi": "Tỉ lệ tuyển 100 chọi 1. Giờ hiểu sao người ta nói Hell Joseon.", "eng": "The intake is 100 to 1. I get why people say Hell Joseon.", "kor": "공채 100대 1이래. 헬조선 소리가 왜 나오는지 알 것 같아."}], "definition": "영어 ''hell(지옥)''과 옛 국호 ''조선''을 붙인 합성어. 경쟁·집값·취업난 탓에 한국에서 사는 게 지옥 같고 노력해도 나아지지 않는다는 청년층의 자조와 사회 비판을 담는다.", "definition_i18n": {"de": "Mischung aus englisch ''hell'' und Joseon, Koreas altem Dynastienamen. Es transportiert Selbstspott und Sozialkritik junger Koreaner: Konkurrenz, Wohnkosten und Jobmarkt machen das Leben höllisch, egal wie sehr man sich anstrengt.", "en": "A blend of English ''hell'' and Joseon, Korea''s old dynastic name. It carries young Koreans'' self-mockery and social critique: that competition, housing costs and the job market make life here hellish no matter how hard you try.", "es": "Mezcla del inglés ''hell'' y Joseon, el antiguo nombre dinástico de Corea. Expresa la autoburla y crítica social de los jóvenes: competencia, vivienda y paro hacen la vida infernal por mucho que te esfuerces.", "ja": "英語の「hell(地獄)」と旧国号「朝鮮」の合成語。競争・住宅価格・就職難のせいで、韓国で生きることは地獄のようで努力しても報われないという若年層の自嘲と社会批判を含む。", "vi": "Ghép từ ''hell'' (địa ngục) trong tiếng Anh với Joseon, quốc hiệu cũ của Hàn Quốc. Nó mang sự tự giễu và phê phán xã hội của giới trẻ: cạnh tranh, giá nhà và thất nghiệp khiến sống ở đây như địa ngục dù cố gắng đến đâu."}}]'::jsonb, '2010년 1월 디시인사이드 역사 갤러리에서 처음 등장한 것으로 알려져 있다. 이후 인터넷 커뮤니티를 중심으로 쓰이다가 2015년 수저계급론 논의와 맞물려 SNS·언론까지 퍼지며 그해 대표 신조어가 됐다.', '{"de": "Erstmals im Januar 2010 im Geschichtsforum von DCInside belegt. Es kursierte in Online-Communities und verbreitete sich um 2015 mit der ''Löffelklassen''-Debatte in sozialen Medien und Presse — das Wort des Jahres.", "en": "First recorded in January 2010 on DCInside''s history board. It circulated in online communities, then spread to social media and the press around 2015 alongside the ''spoon class'' debate, becoming that year''s signature coinage.", "es": "Aparece por primera vez en enero de 2010 en el foro de historia de DCInside. Circuló en comunidades online y hacia 2015 saltó a redes y prensa junto al debate de las ''clases de cuchara'', volviéndose la palabra del año.", "ja": "2010年1月、DCインサイドの歴史ギャラリーで初めて登場したとされる。ネットコミュニティで使われた後、2015年の「スプーン階級論」議論と重なりSNSや報道にも広がり、その年を代表する新造語となった。", "vi": "Xuất hiện lần đầu tháng 1/2010 trên chuyên mục lịch sử của DCInside. Từ này lan trong các cộng đồng mạng rồi bùng ra mạng xã hội và báo chí quanh năm 2015 cùng tranh luận ''thuyết giai cấp thìa'', thành từ mới tiêu biểu năm đó."}'::jsonb, '주로 취업·집값·노동 환경을 한탄할 때 쓴다. 사회 비판이 섞인 무거운 표현이라 농담처럼 던져도 진지하게 받아들여질 수 있고, 외국인이 한국을 두고 쓰면 불쾌하게 들릴 수 있으니 주의.', '{"de": "Meist beim Klagen über Jobs, Wohnkosten oder Arbeitsbedingungen. Es enthält echte Sozialkritik — auch scherzhaft wirkt es schwer, und von Ausländern über Korea gesagt kann es beleidigend klingen.", "en": "Mostly used when venting about jobs, housing or working conditions. It carries real social criticism, so even a joking use can land heavily — and coming from a foreigner about Korea it can sound offensive.", "es": "Se usa al quejarse del empleo, la vivienda o las condiciones laborales. Lleva crítica social real, así que incluso en broma pesa; dicho por un extranjero sobre Corea puede sonar ofensivo.", "ja": "就職・住宅・労働環境を嘆くときに使う。社会批判を含む重い表現なので冗談でも真剣に受け取られることがあり、外国人が韓国について使うと不快に響く場合がある。", "vi": "Thường dùng khi than về việc làm, giá nhà hay điều kiện lao động. Nó mang phê phán xã hội thật sự nên dù nói đùa vẫn nặng nề, và người nước ngoài nói về Hàn Quốc có thể gây khó chịu."}'::jsonb, array['흙수저','이생망','사축'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Hell Joseon (Korea as a hellish place to live)"}, {"lang": "🇯🇵 JA", "text": "ヘル朝鮮(生きづらい韓国)"}, {"lang": "🇨🇳 ZH", "text": "地狱朝鲜(讽刺韩国难以生存)"}, {"lang": "🇻🇳 VI", "text": "Hell Joseon (Hàn Quốc như địa ngục)"}, {"lang": "🇪🇸 ES", "text": "Hell Joseon (Corea como un infierno)"}, {"lang": "🇩🇪 DE", "text": "Hell Joseon (Korea als Hölle)"}]'::jsonb),
('449', '흙수저', 'Heuk-Su-Jeo', 'new-slang', '가난한 집안에서 태어나 물려받을 게 없는 사람', '{"de": "Jemand aus armem Haus ohne Erbe", "en": "Someone born poor with no family wealth to inherit", "es": "Alguien nacido pobre, sin herencia familiar", "ja": "貧しい家に生まれ、相続するものがない人", "vi": "Người sinh ra trong nhà nghèo, không có gì để thừa kế"}'::jsonb, '[흑쑤저]', '[{"type": "명사", "examples": [{"de": "Ich bin Erdlöffel, ich musste die Studiengebühren selbst verdienen.", "es": "Soy cuchara de tierra, así que me pagué la matrícula desde el principio.", "ja": "私は土スプーンだから学費から自分で稼ぐしかなかった。", "vi": "Tớ là thìa đất nên học phí phải tự kiếm từ đầu.", "eng": "I''m a dirt spoon, so I had to earn my own tuition from day one.", "kor": "나는 흙수저라 등록금부터 내가 벌어야 했어."}, {"de": "Sobald Gold- und Erdlöffel zur Sprache kommen, kippt die Stimmung.", "es": "En cuanto salen las cucharas de oro y de tierra, el ambiente se enfría.", "ja": "金スプーン・土スプーンの話が出ると空気が重くなる。", "vi": "Cứ nhắc thìa vàng thìa đất là không khí chùng xuống.", "eng": "The room goes quiet the second gold spoons and dirt spoons come up.", "kor": "금수저 흙수저 얘기 나오면 분위기 싸해져."}], "definition": "''흙''과 ''수저''를 합친 말. 부모의 재산·인맥에 따라 출발선이 정해진다는 ''수저계급론''에서 금수저-은수저-동수저-흙수저 중 맨 아래를 가리킨다. 아무리 노력해도 계층 이동이 어렵다는 체념이 깔려 있다.", "definition_i18n": {"de": "''Erde'' + ''Löffel''. In der ''Löffelklassen-Theorie'' (Gold, Silber, Bronze, Erde) die unterste Stufe: Die Startlinie bestimmen Vermögen und Beziehungen der Eltern, und Fleiß allein reicht selten zum Aufstieg.", "en": "''Dirt'' + ''spoon''. In the ''spoon class theory'' — gold, silver, bronze, dirt — it is the bottom rung, meaning your starting line is set by your parents'' wealth and connections. It carries the resignation that effort alone rarely moves you up.", "es": "''Tierra'' + ''cuchara''. En la ''teoría de las clases de cuchara'' (oro, plata, bronce, tierra) es el escalón más bajo: tu punto de partida lo fija la riqueza y los contactos de tus padres, y el esfuerzo rara vez basta para subir.", "ja": "「土」と「スプーン」の合成語。親の財産や人脈で出発点が決まるという「スプーン階級論」で、金・銀・銅・土のうち最下位を指す。努力しても階層移動が難しいという諦めが込められている。", "vi": "''Đất'' + ''thìa''. Trong ''thuyết giai cấp thìa'' (vàng, bạc, đồng, đất) đây là bậc thấp nhất: vạch xuất phát do tài sản và quan hệ của cha mẹ quyết định, và cố gắng thôi hiếm khi đủ để đi lên."}}]'::jsonb, '영어 관용구 ''born with a silver spoon in one''s mouth''가 바탕이다. 은수저가 먼저 쓰이다 더 값진 금수저로 대체됐고, 여기에 대비되는 최하위로 ''흙수저''가 만들어졌다. 2015년 청년층 사이에서 ''수저계급론'' 담론이 퍼지며 그해 대표 신조어로 꼽혔다.', '{"de": "Geht auf die englische Redewendung ''born with a silver spoon in one''s mouth'' zurück. Erst Silber, dann das wertvollere Gold — und als Gegenpol ganz unten entstand der ''Erdlöffel''. 2015 verbreitete sich der Löffelklassen-Diskurs unter jungen Koreanern und machte es zum Wort des Jahres.", "en": "Rooted in the English idiom ''born with a silver spoon in one''s mouth''. Silver came first, was upgraded to gold, and ''dirt spoon'' was coined as its opposite at the bottom. The ''spoon class'' discourse spread among young Koreans in 2015, making it a word of that year.", "es": "Nace del modismo inglés ''born with a silver spoon in one''s mouth''. Primero fue la plata, luego el oro, más valioso, y como opuesto se acuñó la ''cuchara de tierra''. El discurso de las clases de cuchara se difundió entre los jóvenes en 2015 y fue palabra del año.", "ja": "英語の慣用句「born with a silver spoon in one''s mouth」が土台。まず銀スプーンが使われ、より価値の高い金スプーンに置き換わり、その対極の最下位として「土スプーン」が作られた。2015年に若年層で「スプーン階級論」が広まり、その年を代表する新造語となった。", "vi": "Bắt nguồn từ thành ngữ tiếng Anh ''born with a silver spoon in one''s mouth''. Ban đầu là thìa bạc, sau đổi thành thìa vàng quý hơn, và ''thìa đất'' được tạo ra làm bậc đối lập thấp nhất. Tranh luận ''giai cấp thìa'' lan trong giới trẻ năm 2015, thành từ mới tiêu biểu năm đó."}'::jsonb, '자신을 낮춰 ''나 흙수저야''처럼 쓰는 게 가장 흔하다. 남을 두고 ''쟤 흙수저래''라고 하면 무례하니 피할 것. 반대말은 금수저.', '{"de": "Meist über sich selbst gesagt: ''Ich bin Erdlöffel''. Über andere ist es unhöflich — besser vermeiden. Das Gegenteil ist 금수저 (Goldlöffel).", "en": "Most often said about yourself — ''I''m a dirt spoon.'' Calling someone else one is rude, so avoid it. The opposite is 금수저 (gold spoon).", "es": "Se usa sobre todo en primera persona: ''soy cuchara de tierra''. Decírselo a otro es grosero, mejor evitarlo. Lo contrario es 금수저 (cuchara de oro).", "ja": "「私は土スプーン」のように自分を下げて使うのが一般的。他人を指して言うと失礼なので避けること。反対語は金スプーン。", "vi": "Thường dùng để nói về chính mình: ''tớ là thìa đất''. Gọi người khác như vậy là bất lịch sự, nên tránh. Từ trái nghĩa là 금수저 (thìa vàng)."}'::jsonb, array['헬조선','이생망'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Dirt spoon (born with nothing)"}, {"lang": "🇯🇵 JA", "text": "土スプーン(貧しい家の出)"}, {"lang": "🇨🇳 ZH", "text": "土汤匙(出身贫寒)"}, {"lang": "🇻🇳 VI", "text": "Thìa đất (sinh ra trong nghèo khó)"}, {"lang": "🇪🇸 ES", "text": "Cuchara de tierra (sin herencia)"}, {"lang": "🇩🇪 DE", "text": "Erdlöffel (ohne Erbe geboren)"}]'::jsonb),
('450', '마기꾼', 'Ma-Gi-Kkun', 'new-slang', '마스크를 벗으면 상상과 딴판인 사람', '{"de": "Jemand, der ohne Maske ganz anders aussieht als gedacht", "en": "Someone who looks nothing like you imagined once the mask is off", "es": "Alguien que no se parece nada a lo imaginado al quitarse la mascarilla", "ja": "マスクを外すと想像と全然違う人", "vi": "Người bỏ khẩu trang ra thì khác hẳn tưởng tượng"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Beim Blind Date — Maske ab, und da stand jemand ganz anderes. Voll der Maskenbetrug.", "es": "Fui a una cita a ciegas y al quitarse la mascarilla era otra persona. Puro fraude de mascarilla.", "ja": "合コン行ったらマスク外した瞬間別人だった。完全にマスク詐欺。", "vi": "Đi hẹn hò mù mà bỏ khẩu trang ra là người khác luôn. Đúng chuẩn lừa khẩu trang.", "eng": "Met my blind date, and once the mask came off it was a whole different person. Total mask-fraud.", "kor": "소개팅 나갔는데 마스크 벗으니까 딴사람이더라. 완전 마기꾼."}, {"de": "Ich trau mich nicht, die Maske abzunehmen — nicht dass sie mich auch Maskenbetrug nennen.", "es": "Me da miedo quitármela por si me llaman fraude de mascarilla.", "ja": "自分もマスク詐欺って言われそうで外せない。", "vi": "Tớ sợ bị gọi là lừa khẩu trang nên chẳng dám bỏ ra.", "eng": "I''m scared to take my mask off in case they call me a mask-fraud too.", "kor": "나도 마기꾼 소리 들을까 봐 마스크 못 벗겠어."}], "definition": "''마스크''와 ''사기꾼''을 합친 말. 마스크를 쓴 얼굴만 보고 상상한 인상과 벗은 얼굴이 크게 달라 속은 기분이 들 때 쓴다. 보통 마스크 쓴 쪽이 더 나아 보였던 경우를 가리킨다.", "definition_i18n": {"de": "Mischung aus ''Maske'' und ''Betrüger''. Man sagt es, wenn das Gesicht, das man sich unter der Maske vorgestellt hat, ohne sie ganz anders aussieht und man sich getäuscht fühlt — meist wenn es mit Maske besser wirkte.", "en": "A blend of ''mask'' and ''fraudster''. Used when the face you pictured from the masked half turns out very different unmasked, so you feel tricked — usually when the masked version looked better.", "es": "Mezcla de ''mascarilla'' y ''estafador''. Se usa cuando la cara que imaginabas con mascarilla resulta muy distinta sin ella y te sientes engañado — normalmente cuando con mascarilla se veía mejor.", "ja": "「マスク」と「詐欺師」の合成語。マスク姿から想像した顔と、外した顔が大きく違って騙された気分になるときに使う。たいていマスク姿のほうが良く見えていた場合を指す。", "vi": "Ghép ''khẩu trang'' và ''kẻ lừa đảo''. Dùng khi gương mặt bạn hình dung qua phần đeo khẩu trang hóa ra rất khác lúc bỏ ra, khiến bạn thấy như bị lừa — thường là lúc đeo trông đẹp hơn."}}]'::jsonb, '코로나19로 마스크 착용이 일상이 된 2020년 무렵, 얼굴 절반만 보이는 상황을 유머로 풀어내며 생겼다. 언론 신조어 사전과 방역 관련 기사에서 ''코로나 신조어''로 함께 소개됐다.', '{"de": "Entstand um 2020, als Masken durch COVID-19 Alltag wurden und nur das halbe Gesicht sichtbar war — als Scherz über diese Lücke. Zeitungen führten es unter den ''Corona-Neologismen''.", "en": "Coined around 2020, when COVID-19 made masks routine and only half a face was visible, as a joke about that gap. Newspapers listed it among ''COVID coinages'' in slang columns and pandemic reporting.", "es": "Acuñada hacia 2020, cuando la COVID-19 hizo rutina la mascarilla y solo se veía media cara, como broma sobre ese desfase. La prensa la incluyó entre los ''neologismos del COVID''.", "ja": "新型コロナでマスク着用が日常になった2020年頃、顔が半分しか見えない状況をユーモアにして生まれた。新聞の新造語コラムや防疫関連記事で「コロナ新造語」として紹介された。", "vi": "Ra đời khoảng năm 2020, khi COVID-19 khiến khẩu trang thành thường ngày và chỉ thấy nửa mặt, như một câu đùa về khoảng cách đó. Báo chí xếp nó vào nhóm ''từ mới thời COVID''."}'::jsonb, '대개 자기 자신이나 상황을 두고 농담처럼 쓴다. 상대 면전에 대고 ''마기꾼''이라고 하면 외모 비하로 받아들여지니 쓰지 말 것.', '{"de": "Meist ein Scherz über sich selbst oder die Situation. Jemandem ins Gesicht gesagt ist es eine Beleidigung des Aussehens — lass es.", "en": "Usually a joke about yourself or the situation. Saying it to someone''s face reads as an insult about their looks — don''t.", "es": "Normalmente es una broma sobre uno mismo o la situación. Decírselo a alguien a la cara suena a insulto sobre su físico — no lo hagas.", "ja": "たいていは自分や状況について冗談として使う。面と向かって「マスク詐欺」と言うと容姿の侮辱になるので言わないこと。", "vi": "Thường là đùa về bản thân hoặc tình huống. Nói thẳng vào mặt người khác thì thành chê ngoại hình — đừng làm vậy."}'::jsonb, array['확찐자','얼짱','외모정병'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Mask fraud (looks different unmasked)"}, {"lang": "🇯🇵 JA", "text": "マスク詐欺"}, {"lang": "🇨🇳 ZH", "text": "口罩诈骗(摘下口罩判若两人)"}, {"lang": "🇻🇳 VI", "text": "Lừa khẩu trang"}, {"lang": "🇪🇸 ES", "text": "Fraude de mascarilla"}, {"lang": "🇩🇪 DE", "text": "Maskenbetrug"}]'::jsonb),
('451', '이생망', 'I-Saeng-Mang', 'new-slang', '''이번 생은 망했다'' — 다 망했다고 과장해 자조하는 말', '{"de": "''Dieses Leben ist ruiniert'' — übertriebener Selbstspott nach einem Patzer", "en": "''This life is ruined'' — over-the-top self-mockery when you mess up", "es": "''Esta vida está arruinada'' — autoburla exagerada al meter la pata", "ja": "「今世は終わった」— 失敗したときの大げさな自嘲", "vi": "''Kiếp này tiêu rồi'' — tự giễu phóng đại khi làm hỏng chuyện"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Ich hab im Interview den Firmennamen falsch gesagt … dieses Leben ist vorbei.", "es": "Dije mal el nombre de la empresa en la entrevista… esta vida se acabó.", "ja": "面接で会社名を間違えた…人生終わった。", "vi": "Phỏng vấn mà nói sai tên công ty… kiếp này tiêu rồi.", "eng": "I got the company''s name wrong in the interview… this life is over.", "kor": "면접에서 회사 이름 틀리게 말했어… 이생망."}, {"de": "Du bist erst 23 — etwas früh, dein Leben abzuschreiben.", "es": "Solo tienes veintitrés, un poco pronto para dar la vida por perdida.", "ja": "人生終わったって言うにはまだ23歳でしょ、しっかりして。", "vi": "Mới hai ba tuổi mà đòi kiếp này tiêu, tỉnh lại đi.", "eng": "You''re only twenty-three — bit early to call your life over.", "kor": "이생망이라고 하기엔 아직 스물셋이잖아, 정신 차려."}], "definition": "''이번 생은 망했다''를 세 글자로 줄인 말. 큰 실수를 했거나 일이 뜻대로 안 풀릴 때 스스로를 낮추며 과장되게 절망을 드러낸다. 취업난·경제난을 겪는 청년층의 진지한 체념으로도, 사소한 실수에 붙이는 가벼운 농담으로도 쓰인다.", "definition_i18n": {"de": "Kurzform von ''이번 생은 망했다'' (dieses Leben ist ruiniert). Man sagt es nach einem groben Fehler oder wenn nichts klappt — mit übertriebener Verzweiflung. Es reicht von echter Resignation junger Koreaner über Jobs und Geld bis zum leichten Scherz über einen Patzer.", "en": "A three-syllable clip of ''이번 생은 망했다'' (this life is ruined). You say it after a big mistake or when nothing goes your way, putting yourself down with exaggerated despair. It runs from young Koreans'' genuine resignation about jobs and money to a light joke over a tiny slip.", "es": "Abreviatura de ''이번 생은 망했다'' (esta vida está arruinada). Se dice tras un error gordo o cuando nada sale bien, con desesperación exagerada. Va desde la resignación real de los jóvenes ante el paro y el dinero hasta la broma ligera por un desliz.", "ja": "「今回の人生は終わった」を3文字に縮めた語。大きなミスをしたり物事が思い通りにいかないとき、自分を落として大げさに絶望を表す。就職難・経済難を抱える若年層の本気の諦めから、些細な失敗への軽い冗談まで幅広く使う。", "vi": "Viết tắt ba âm của ''이번 생은 망했다'' (kiếp này tiêu rồi). Nói khi mắc lỗi lớn hoặc mọi thứ không như ý, tự hạ mình với vẻ tuyệt vọng phóng đại. Từ sự buông xuôi thật của giới trẻ trước thất nghiệp và tiền bạc, đến câu đùa nhẹ vì lỗi vặt."}}]'::jsonb, '인터넷 커뮤니티와 SNS에서 자연스럽게 굳어진 줄임말로, 특정 인물이나 사건에서 시작됐다는 확정된 기록은 없다. 2010년대 중후반 취업난·경제난을 겪는 청년층 사이에서 널리 퍼졌고, 언론 신조어 사전에도 등재됐다.', '{"de": "Der Ausdruck setzte sich organisch in Online-Communities und sozialen Medien durch; eine einzelne Person oder ein Ereignis als Ursprung ist nicht belegt. Mitte bis Ende der 2010er verbreitete er sich unter jungen Koreanern auf einem harten Arbeitsmarkt und stand später in Neologismus-Lexika der Presse.", "en": "It settled into use organically across online communities and social media; no single person or event is documented as its source. It spread widely among young Koreans facing a tough job market in the mid-to-late 2010s and was later listed in newspaper slang dictionaries.", "es": "Se consolidó de forma orgánica en comunidades online y redes; no hay una persona o suceso documentado como origen. Se extendió entre los jóvenes ante el paro a mediados y finales de los 2010 y llegó a los diccionarios de neologismos de la prensa.", "ja": "ネットコミュニティやSNSで自然に定着した略語で、特定の人物や出来事が起源だという確定した記録はない。2010年代半ば以降、就職難に直面する若年層で広まり、新聞の新造語辞典にも掲載された。", "vi": "Từ này định hình tự nhiên trên các cộng đồng mạng và mạng xã hội; không có ghi chép chắc chắn về một người hay sự kiện khởi nguồn. Nó lan rộng trong giới trẻ đối mặt thất nghiệp giữa và cuối thập niên 2010, rồi vào cả từ điển từ mới của báo chí."}'::jsonb, '보통 자기 자신에게만 쓴다. 남에게 ''너 이생망이야''라고 하면 심한 모욕이 된다. 가볍게 던지는 경우가 많지만 상대가 실제로 힘든 상황이면 농담으로 받지 않을 수 있으니 분위기를 볼 것.', '{"de": "Sagt man normalerweise nur über sich selbst; jemand anderem gesagt ist es eine harte Beleidigung. Meist locker gemeint — aber wenn es dem Gegenüber wirklich schlecht geht, kommt es nicht als Scherz an.", "en": "Normally said only about yourself; telling someone else ''you''re 이생망'' is a harsh insult. It''s usually thrown out lightly, but if the other person is genuinely struggling they may not take it as a joke — read the room.", "es": "Normalmente solo se dice de uno mismo; decírselo a otro es un insulto duro. Suele soltarse a la ligera, pero si la otra persona lo está pasando mal puede no tomarlo a broma — lee el ambiente.", "ja": "普通は自分にだけ使う。他人に「お前は이생망だ」と言えばひどい侮辱になる。軽く言うことが多いが、相手が本当につらい状況なら冗談として受け取られないので空気を読むこと。", "vi": "Thường chỉ nói về bản thân; bảo người khác ''이생망'' là xúc phạm nặng. Hay được nói đùa, nhưng nếu người kia đang thật sự khó khăn thì họ có thể không coi là đùa — hãy để ý không khí."}'::jsonb, array['헬조선','흙수저','스불재'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "This life is over / I''ve ruined my life"}, {"lang": "🇯🇵 JA", "text": "今世は終わった(人生詰んだ)"}, {"lang": "🇨🇳 ZH", "text": "这辈子完了"}, {"lang": "🇻🇳 VI", "text": "Kiếp này tiêu rồi"}, {"lang": "🇪🇸 ES", "text": "Esta vida está arruinada"}, {"lang": "🇩🇪 DE", "text": "Dieses Leben ist gelaufen"}]'::jsonb),
('452', '삐끼삐끼', 'Ppi-Kki-Ppi-Kki', 'new-slang', '야구 응원가에서 나온 후렴 소리이자 그 춤', '{"de": "Ein Chant-Laut aus einem Baseball-Anfeuerungslied und der zugehörige Tanz", "en": "A chant sound from a baseball cheer song, and the dance that goes with it", "es": "El sonido del estribillo de un cántico de béisbol y su baile", "ja": "野球の応援歌から生まれた掛け声と、その振り付け", "vi": "Tiếng điệp khúc từ bài cổ vũ bóng chày, và điệu nhảy đi kèm"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Wenn dieser Song läuft, machen alle den Ppikki-Ppikki. Man kann gar nicht anders.", "es": "Cuando suena esta canción todos hacen el ppikki-ppikki. No puedes resistirte.", "ja": "この曲かかったらみんなピッキピッキ踊る。踊らずにいられない。", "vi": "Cứ bật bài này là ai cũng nhảy ppikki-ppikki. Không nhảy không được.", "eng": "When this song drops everyone does the ppikki-ppikki. You can''t not.", "kor": "이 노래 나오면 다들 삐끼삐끼 춰. 안 출 수가 없어."}, {"de": "Das Cheerleader-Ppikki-Ppikki-Video ging ja auch im Ausland durch die Decke.", "es": "El vídeo del ppikki-ppikki de la animadora también arrasó fuera, ¿no?", "ja": "チアのピッキピッキ動画、海外でも大騒ぎだったよね。", "vi": "Cái clip ppikki-ppikki của cheerleader nổi cả ở nước ngoài đó.", "eng": "That cheerleader ppikki-ppikki clip blew up overseas too, remember?", "kor": "치어리더 삐끼삐끼 영상 외국에서도 난리였잖아."}], "definition": "프로야구 KIA 타이거즈 응원가 리믹스의 후렴이 ''삐끼삐끼''처럼 들린 데서 나온 소리. 지금은 그 소리에 맞춘 치어리더 춤 자체와, 신나게 몸을 흔드는 상황 전반을 가리킨다.", "definition_i18n": {"de": "Der Laut, den man im Hook eines geremixten KIA-Tigers-Anfeuerungslieds hörte. Heute bezeichnet er den Cheerleader-Tanz dazu und allgemein jeden Moment ausgelassenen Mitwippens.", "en": "The sound people heard in the hook of a remixed KIA Tigers cheer song. It now names the cheerleader dance set to it, and by extension any moment of joyfully bopping along.", "es": "El sonido que la gente oía en el estribillo de un cántico remezclado de los KIA Tigers. Hoy nombra el baile de las animadoras y, por extensión, cualquier momento de moverse con alegría.", "ja": "プロ野球KIAタイガースの応援歌リミックスのサビが「ピッキピッキ」と聞こえたことから生まれた音。今ではそれに合わせたチアの振り付け自体や、楽しく体を揺らす場面全般を指す。", "vi": "Âm thanh người ta nghe được ở đoạn hook bài cổ vũ remix của đội KIA Tigers. Giờ nó chỉ luôn điệu nhảy cheerleader theo nhạc đó, và rộng hơn là mọi khoảnh khắc lắc lư vui vẻ."}}]'::jsonb, '프로야구 KIA 타이거즈 응원가 리믹스의 후렴이 ''삐끼삐끼''로 들린다는 데서 시작됐다. 2024년 치어리더 이주은이 화장을 고치다 급히 춤을 추는 영상이 SNS에서 크게 퍼지며 한국을 넘어 해외 매체까지 다룰 만큼 유명해졌다. 원곡 표기는 매체마다 인용이 조금씩 달라 확정하지 않는다.', '{"de": "Es begann damit, dass der Hook eines geremixten KIA-Tigers-Songs wie ''Ppikki-Ppikki'' klang. 2024 ging ein Clip der Cheerleaderin Lee Ju-eun viral, die sich mitten beim Nachschminken in den Tanz stürzt — auch Medien außerhalb Koreas berichteten. Die Quellen nennen den Originaltitel leicht unterschiedlich, daher bleibt er hier offen.", "en": "It began with the hook of a remixed KIA Tigers cheer song sounding like ''ppikki-ppikki''. In 2024 a clip of cheerleader Lee Ju-eun dashing into the dance mid-touch-up went viral and drew coverage well beyond Korea. Sources cite the original track slightly differently, so it is left unstated here.", "es": "Empezó porque el estribillo remezclado de los KIA Tigers sonaba a ''ppikki-ppikki''. En 2024 un vídeo de la animadora Lee Ju-eun lanzándose al baile mientras se retocaba el maquillaje se hizo viral y llegó a medios de fuera de Corea. Las fuentes citan la canción original de forma algo distinta, así que no se fija aquí.", "ja": "KIAタイガースの応援歌リミックスのサビが「ピッキピッキ」と聞こえたことが発端。2024年、チアリーダーのイ・ジュウンが化粧直しの途中で慌てて踊る動画がSNSで拡散し、韓国を越えて海外メディアも取り上げるほどになった。原曲の表記は媒体ごとに引用が異なるため確定しない。", "vi": "Bắt đầu từ việc đoạn hook remix bài cổ vũ KIA Tigers nghe như ''ppikki-ppikki''. Năm 2024, clip cheerleader Lee Ju-eun đang dặm phấn thì vội nhảy theo đã lan truyền mạnh và được cả báo nước ngoài đưa tin. Các nguồn ghi tên bài gốc hơi khác nhau nên ở đây không khẳng định."}'::jsonb, '신나는 춤이나 응원 장면을 묘사할 때, 혹은 같이 추자고 부추길 때 쓴다. ''삐끼삐끼 춤'', ''삐끼삐끼 추다'' 형태가 흔하다. 호객꾼을 뜻하는 기존 단어 ''삐끼''와는 전혀 다른 말이다.', '{"de": "Für einen mitreißenden Tanz oder eine Anfeuerungsszene — oder um jemanden zum Mitmachen zu bewegen. Üblich sind 삐끼삐끼 춤 und 삐끼삐끼 추다. Mit dem alten Wort 삐끼 (Kundenfänger) hat es nichts zu tun.", "en": "Used to describe an upbeat dance or cheering scene, or to egg someone into joining. Common forms are 삐끼삐끼 춤 (the ppikki-ppikki dance) and 삐끼삐끼 추다 (to do it). It is unrelated to the older word 삐끼, meaning a street tout.", "es": "Se usa para describir un baile animado o una escena de ánimo, o para invitar a alguien a sumarse. Formas habituales: 삐끼삐끼 춤 y 삐끼삐끼 추다. No tiene relación con la palabra antigua 삐끼, ''captador de clientes''.", "ja": "楽しいダンスや応援シーンを表すとき、あるいは一緒に踊ろうと誘うときに使う。「ピッキピッキ춤」「ピッキピッキ추다」の形が多い。客引きを意味する既存語「삐끼」とは全く別の語。", "vi": "Dùng khi mô tả điệu nhảy sôi động hay cảnh cổ vũ, hoặc rủ ai đó nhảy cùng. Hay gặp dạng 삐끼삐끼 춤 và 삐끼삐끼 추다. Nó không liên quan gì tới từ cũ 삐끼 nghĩa là người chèo kéo khách."}'::jsonb, array['챌린지','직캠','최애'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Ppikki-ppikki (viral baseball cheer dance)"}, {"lang": "🇯🇵 JA", "text": "ピッキピッキ(野球応援ダンス)"}, {"lang": "🇨🇳 ZH", "text": "啤叽啤叽(棒球应援舞)"}, {"lang": "🇻🇳 VI", "text": "Ppikki-ppikki (điệu nhảy cổ vũ bóng chày)"}, {"lang": "🇪🇸 ES", "text": "Ppikki-ppikki (baile viral de béisbol)"}, {"lang": "🇩🇪 DE", "text": "Ppikki-Ppikki (viraler Baseball-Cheertanz)"}]'::jsonb),
('453', '확찐자', 'Hwak-Jjin-Ja', 'new-slang', '집에만 있다가 살이 확 쪄버린 사람', '{"de": "Jemand, der vom Daheimbleiben stark zugenommen hat", "en": "Someone who piled on weight from staying indoors", "es": "Alguien que engordó de golpe por quedarse en casa", "ja": "家にこもって一気に太った人", "vi": "Người tăng cân vù vù vì ở nhà suốt"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Zwei Monate daheim, fünf Kilo mehr. Ich bin ein bestätigter Dickfall.", "es": "Dos meses en casa y cinco kilos más. Soy un caso confirmado… de gordura.", "ja": "引きこもり2ヶ月で5キロ増えた。私、確ブト者。", "vi": "Ở nhà hai tháng tăng 5 ký. Tớ là ca ''dương tính'' béo rồi.", "eng": "Two months indoors and I''m up five kilos. I''m officially a confirmed-fat case.", "kor": "집콕 두 달 만에 5kg 쪘어. 나 확찐자야."}, {"de": "Wir Dickfälle aus der Klasse melden uns zusammen im Fitnessstudio an.", "es": "Los que engordamos en clase nos apuntamos juntos al gimnasio.", "ja": "クラスの太った組でジム契約することにした。", "vi": "Đám tăng cân trong lớp rủ nhau đăng ký phòng gym.", "eng": "All of us who blew up over lockdown are signing up for the gym together.", "kor": "우리 반 확찐자들끼리 헬스 끊기로 했다."}], "definition": "코로나19 ''확진자''의 발음 [확찐자]에 ''살이 확 쪘다''를 겹쳐 만든 말장난. 외출을 못 하고 집에 머무는 동안 운동량이 줄어 체중이 크게 늘어난 사람을 가리킨다.", "definition_i18n": {"de": "Ein Wortspiel: 확진자 (bestätigter COVID-Fall) klingt wie 확 찐 자, ''wer schnell zugenommen hat''. Gemeint ist jemand, der zu Hause ohne Bewegung viel Gewicht zugelegt hat.", "en": "A pun: 확진자 (a confirmed COVID case) is pronounced the same as 확 찐 자, ''one who got fat fast''. It refers to someone who gained a lot of weight while stuck at home with no exercise.", "es": "Un juego de palabras: 확진자 (''caso confirmado'') suena igual que 확 찐 자, ''el que engordó de golpe''. Designa a quien ganó mucho peso encerrado en casa sin ejercicio.", "ja": "新型コロナの「確診者(확진자)」の発音[ファクチンジャ]に「一気に太った」を重ねた言葉遊び。外出できず家にいる間に運動量が減り、体重が大きく増えた人を指す。", "vi": "Chơi chữ: 확진자 (''ca dương tính'') phát âm giống 확 찐 자, ''người béo lên vù vù''. Chỉ người tăng cân nhiều vì ở nhà, không vận động."}}]'::jsonb, '코로나19 초기인 2020년, 방역 수칙을 지키느라 집에 머물면서 체중이 늘어난 현상을 ''확진자''와 발음이 같은 점을 이용해 비튼 말. 같은 시기 ''언택트 취업'', ''코파라치'' 등과 함께 코로나 신조어로 언론에 소개됐다.', '{"de": "Entstand Anfang 2020, als Corona-Regeln Daheimbleiben und Zunehmen bedeuteten; es verdreht 확진자 (bestätigter Fall), das gleich klingt. Zeitungen führten es neben anderen Pandemie-Neologismen.", "en": "Coined in early 2020, when following COVID rules meant staying home and putting on weight; it twists 확진자 (confirmed case), which sounds identical. Newspapers listed it alongside other pandemic coinages of the time.", "es": "Acuñada a principios de 2020, cuando cumplir las normas anti-COVID significaba quedarse en casa y engordar; retuerce 확진자 (''caso confirmado''), que suena igual. La prensa la listó junto a otros neologismos de la pandemia.", "ja": "コロナ初期の2020年、防疫を守って家にいるうちに体重が増えた現象を、同じ発音の「確診者」にかけて捻った語。当時の他のコロナ新造語とともに報道で紹介された。", "vi": "Ra đời đầu năm 2020, khi tuân thủ quy định chống dịch đồng nghĩa ở nhà và tăng cân; nó bẻ chữ 확진자 (''ca xác nhận'') vốn phát âm y hệt. Báo chí xếp nó cùng các từ mới thời dịch khác."}'::jsonb, '자기 자신을 두고 웃으며 쓰는 게 원칙이다. 감염병 확진자를 연상시키는 말장난이라 남의 체형을 두고 쓰면 모욕이 될 수 있고, 실제로 그런 분쟁 사례도 있었다.', '{"de": "Grundsätzlich über sich selbst und mit einem Lachen. Da das Wortspiel auf ''bestätigter Fall'' beruht, kann es über den Körper anderer beleidigend sein — dazu gab es reale Streitfälle.", "en": "As a rule, use it about yourself, with a laugh. Because the pun rides on ''confirmed COVID case'', aiming it at someone else''s body can be insulting — there have been real disputes over exactly that.", "es": "Por norma, úsala sobre ti y en broma. Como el juego se apoya en ''caso confirmado'', dirigirla al cuerpo de otro puede ser un insulto; ha habido conflictos reales por ello.", "ja": "原則として自分について笑いながら使う。感染者を連想させる言葉遊びなので、他人の体型に向けて使うと侮辱になり得るし、実際にそうしたトラブル事例もある。", "vi": "Nguyên tắc là chỉ nói về mình, kèm nụ cười. Vì lối chơi chữ dựa trên ''ca dương tính'', nhắm vào vóc dáng người khác có thể thành xúc phạm — đã có tranh chấp thật vì chuyện này."}'::jsonb, array['마기꾼','오운완','뚠뚠이'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Confirmed-fat case (lockdown weight gain)"}, {"lang": "🇯🇵 JA", "text": "確ブト者(コロナ太り)"}, {"lang": "🇨🇳 ZH", "text": "确胖者(居家发胖)"}, {"lang": "🇻🇳 VI", "text": "Ca ''dương tính'' béo (tăng cân do ở nhà)"}, {"lang": "🇪🇸 ES", "text": "Caso confirmado de kilos (engorde por confinamiento)"}, {"lang": "🇩🇪 DE", "text": "Bestätigter Dickfall (Lockdown-Kilos)"}]'::jsonb),
('454', '댕댕이', 'Daeng-Daeng-I', 'new-slang', '강아지를 귀엽게 부르는 말 (''멍멍이''의 야민정음)', '{"de": "Kosewort für Hund — 멍멍이 mit ähnlich aussehenden Zeichen geschrieben", "en": "A cutesy word for a dog — 멍멍이 rewritten in look-alike letters", "es": "Forma tierna de decir perro: 멍멍이 escrito con letras parecidas", "ja": "犬をかわいく呼ぶ語(「멍멍이」の野民正音表記)", "vi": "Cách gọi cún dễ thương — 멍멍이 viết bằng chữ trông giống"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Unser Hundi war heute beim Friseur. Viel zu süß.", "es": "Hoy peluquearon a nuestro perrete. Demasiado mono.", "ja": "うちのわんこ、今日トリミングしたの。かわいすぎ。", "vi": "Cún nhà tớ nay đi cắt tỉa. Cưng dã man.", "eng": "Our doggo got groomed today. Way too cute.", "kor": "우리 집 댕댕이 오늘 미용했어. 너무 귀여워."}, {"de": "Gassizeit fürs Hundi, ich muss los.", "es": "Toca paseo del perrete, me tengo que ir.", "ja": "わんこの散歩の時間だから出なきゃ。", "vi": "Tới giờ dắt cún đi dạo rồi, tớ phải ra ngoài.", "eng": "It''s doggo walk time, I gotta head out.", "kor": "댕댕이 산책 시간이라 나가야 돼."}], "definition": "강아지를 뜻하는 ''멍멍이''의 ''멍''을 모양이 비슷한 ''댕''으로 바꿔 쓴 말. 글자 모양이 닮은 음절로 일부러 바꿔 쓰는 인터넷 표기법 ''야민정음''의 대표 사례이며, 지금은 원말보다 더 널리 쓰이는 애칭이 됐다.", "definition_i18n": {"de": "멍멍이 (''Hundi''), bei dem 멍 durch das optisch ähnliche 댕 ersetzt wird. Es ist das Paradebeispiel für 야민정음, die Internet-Praxis, Silben durch ähnlich aussehende zu tauschen — heute gebräuchlicher als das Original.", "en": "멍멍이 (doggo) with 멍 swapped for the visually similar 댕. It is the flagship example of 야민정음, the internet habit of replacing syllables with look-alike ones, and it is now a more common pet name than the original.", "es": "멍멍이 (''perrito'') con 멍 cambiado por 댕, que se le parece visualmente. Es el ejemplo estrella del 야민정음, la costumbre de internet de sustituir sílabas por otras parecidas, y hoy es más común que la palabra original.", "ja": "犬を意味する「멍멍이」の「멍」を、形の似た「댕」に替えた語。字形の似た音節にわざと置き換えるネット表記法「野民正音」の代表例で、今では元の語より広く使われる愛称になった。", "vi": "멍멍이 (''cún'') với âm 멍 đổi thành 댕 trông na ná. Đây là ví dụ tiêu biểu của 야민정음, lối viết mạng thay âm tiết bằng âm tiết trông giống, và giờ còn phổ biến hơn cả từ gốc."}}]'::jsonb, '디시인사이드 야구 갤러리에서 시작된 표기 놀이 ''야민정음''(''야갤''+''훈민정음'')의 한 사례다. 2017년 무렵 언론이 다룰 만큼 퍼졌고, 같은 방식으로 귀여워→커여워, 명곡→띵곡 등이 만들어졌다. 한글을 망친다는 비판과 언어 유희라는 옹호가 함께 따라다닌다.', '{"de": "Ein Fall von 야민정음 (''Yagal'' + ''Hunminjeongeum''), einem Schreibspiel aus dem Baseball-Forum von DCInside. Um 2017 war es so verbreitet, dass Medien berichteten; derselbe Trick brachte 커여워 (귀여워) und 띵곡 (명곡) hervor. Es erntet Kritik als Hangul-Zerstörung und Verteidigung als Wortspiel.", "en": "One instance of 야민정음 (''Yagal'' + ''Hunminjeongeum''), a spelling game born on DCInside''s baseball board. It was widespread enough for news coverage by around 2017, and the same trick produced 커여워 (귀여워) and 띵곡 (명곡). It draws both criticism for mangling Hangul and defence as wordplay.", "es": "Un caso de 야민정음 (''Yagal'' + ''Hunminjeongeum''), el juego ortográfico nacido en el foro de béisbol de DCInside. Hacia 2017 ya salía en las noticias, y el mismo truco dio 커여워 (귀여워) y 띵곡 (명곡). Recibe críticas por destrozar el hangul y defensas como juego de palabras.", "ja": "DCインサイド野球ギャラリー発の表記遊び「野民正音」(「野ギャラ」+「訓民正音」)の一例。2017年頃には報道されるほど広まり、同じ方式で귀여워→커여워、명곡→띵곡なども生まれた。ハングルを壊すという批判と、言葉遊びだという擁護が並行している。", "vi": "Một ví dụ của 야민정음 (''Yagal'' + ''Hunminjeongeum''), trò chơi chính tả khởi từ chuyên mục bóng chày của DCInside. Khoảng năm 2017 nó phổ biến tới mức lên báo, và cùng cách đó sinh ra 커여워 (귀여워), 띵곡 (명곡). Nó vừa bị chê phá tiếng Hàn vừa được bênh là chơi chữ."}'::jsonb, '반려견을 귀엽게 부를 때 일상적으로 쓴다. 표준어가 아니므로 글쓰기·공문서에는 쓰지 않지만, SNS나 친구 사이 대화에서는 ''멍멍이''보다 흔하다.', '{"de": "Ein alltäglich-liebevolles Wort für den Hund. Kein Standardkoreanisch — also nicht in formellen Texten; in sozialen Medien und unter Freunden aber gängiger als 멍멍이.", "en": "An everyday affectionate way to call a pet dog. It is not standard Korean, so keep it out of formal writing — but on social media and among friends it is more common than 멍멍이.", "es": "Forma cariñosa y cotidiana de llamar al perro. No es coreano estándar, así que evítalo en textos formales; en redes y entre amigos es más común que 멍멍이.", "ja": "愛犬をかわいく呼ぶ日常語。標準語ではないので文書や公式の場では使わないが、SNSや友人同士では「멍멍이」より一般的。", "vi": "Cách gọi cún cưng thân mật hằng ngày. Không phải tiếng Hàn chuẩn nên tránh dùng trong văn bản trang trọng; còn trên mạng xã hội và giữa bạn bè thì phổ biến hơn cả 멍멍이."}'::jsonb, array['잼민이'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Doggo / pupper"}, {"lang": "🇯🇵 JA", "text": "わんこ(犬の愛称)"}, {"lang": "🇨🇳 ZH", "text": "汪星人(狗狗的昵称)"}, {"lang": "🇻🇳 VI", "text": "Cún / boss cún"}, {"lang": "🇪🇸 ES", "text": "Perrete / perrito"}, {"lang": "🇩🇪 DE", "text": "Hundi / Wuffi"}]'::jsonb),
('455', '마라탕후루', 'Ma-Ra-Tang-Hu-Ru', 'new-slang', '매운 마라탕 먹고 단 탕후루로 마무리하는 10대 코스', '{"de": "Der Teenie-Kombi: scharfer Malatang, danach süßer Tanghulu", "en": "The teen combo: spicy malatang, then sweet tanghulu for dessert", "es": "El combo adolescente: malatang picante y luego tanghulu dulce", "ja": "辛いマーラータンの後に甘いタンフールーで締める10代の定番コース", "vi": "Combo tuổi teen: ăn malatang cay rồi tráng miệng tanghulu ngọt"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Heute wieder Malatang-Tanghulu? Erst scharf, dann süß.", "es": "¿Hoy también malatang-tanghulu? Primero picante y luego dulce.", "ja": "今日もマーラータンフールーでしょ?辛いの食べて甘いので締め。", "vi": "Nay lại malatang-tanghulu hả? Cay trước, ngọt sau.", "eng": "Malatang-tanghulu run again today? Spicy first, sweet to finish.", "kor": "오늘도 마라탕후루 각이지? 매운 거 먹고 단 거로 마무리."}, {"de": "Bei uns machen wirklich alle Grundschulkinder dieses Malatang-Tanghulu.", "es": "Todos los niños de primaria de mi barrio están con el malatang-tanghulu.", "ja": "うちの近所の小学生、みんな本当にマーラータンフールーしてる。", "vi": "Bọn tiểu học khu tớ đứa nào cũng malatang-tanghulu thật.", "eng": "Every elementary kid around here is doing the malatang-tanghulu thing.", "kor": "우리 동네 초등학생들 진짜 다 마라탕후루 하더라."}], "definition": "중국식 매운 국물 요리 ''마라탕''과 과일 설탕 코팅 간식 ''탕후루''를 한 단어로 붙인 말. 매운 걸 먹고 곧바로 단 걸로 입가심하는 조합, 또는 그렇게 먹는 문화 자체를 가리킨다.", "definition_i18n": {"de": "Ein Wort aus 마라탕 (scharfe Suppe chinesischer Art) und 탕후루 (kandierte Fruchtspieße). Es meint die Kombi, etwas Scharfes zu essen und sofort mit etwas Süßem nachzuspülen — und die Esskultur drumherum.", "en": "One word made of 마라탕 (Chinese-style spicy soup) and 탕후루 (sugar-glazed fruit skewers). It names the combo of eating something fiery and immediately washing it down with something sweet — and the food culture around it.", "es": "Una sola palabra formada por 마라탕 (sopa picante china) y 탕후루 (fruta bañada en azúcar). Nombra el combo de comer algo picante y rematar enseguida con algo dulce, y la cultura gastronómica que lo rodea.", "ja": "中華風の辛いスープ「マーラータン」と、果物の飴がけ「タンフールー」を一語にした造語。辛いものを食べてすぐ甘いもので口直しする組み合わせ、またはその食文化そのものを指す。", "vi": "Một từ ghép từ 마라탕 (canh cay kiểu Trung) và 탕후루 (hoa quả bọc đường). Nó chỉ combo ăn món cay rồi ngay lập tức tráng miệng bằng món ngọt, và cả trào lưu ẩm thực quanh nó."}}]'::jsonb, '2022~2023년 무렵 초·중·고등학생 사이에서 마라탕을 먹고 곧장 탕후루로 넘어가는 식습관이 퍼지면서 두 단어가 하나로 붙었다. 같은 이름의 노래(가수 서이브, ''탕탕 후루루루루'' 후렴)가 인스타그램·틱톡에서 크게 유행하며 말 자체도 함께 확산됐다.', '{"de": "Um 2022-2023 aßen Schulkinder Malatang und zogen direkt zum Tanghulu weiter — die beiden Wörter verschmolzen. Ein gleichnamiger Song von Seo Ive mit dem Hook ''Tang-tang hururururu'' ging auf Instagram und TikTok viral und trug den Ausdruck weiter.", "en": "Around 2022-2023 school kids took to eating malatang and heading straight for tanghulu, and the two words fused. A song of the same name by Seo Ive, with its ''tang-tang hururururu'' hook, went viral on Instagram and TikTok and carried the phrase further.", "es": "Hacia 2022-2023 los escolares empezaron a comer malatang y pasar directo al tanghulu, y las dos palabras se fundieron. Una canción homónima de Seo Ive, con su estribillo ''tang-tang hururururu'', se hizo viral en Instagram y TikTok y difundió aún más la expresión.", "ja": "2022〜23年頃、小中高生の間でマーラータンの後すぐタンフールーへ向かう食べ方が広がり、二語が一つになった。同名の楽曲(歌手ソ・イブ、「タンタン フルルルル」のサビ)がInstagramやTikTokで大流行し、語自体も一緒に広まった。", "vi": "Khoảng 2022-2023, học sinh rủ nhau ăn malatang rồi đi thẳng tới tanghulu, và hai từ dính lại làm một. Bài hát cùng tên của ca sĩ Seo Ive, với đoạn hook ''tang-tang hururururu'', gây sốt trên Instagram và TikTok và đẩy cụm từ lan xa hơn."}'::jsonb, '음식 조합을 말할 때도 쓰고, ''오늘 마라탕후루 하자''처럼 동사처럼도 쓴다. 10대 문화를 가리키는 말이라 어른이 쓰면 살짝 따라 하는 느낌이 난다.', '{"de": "Sowohl für die Essenskombi als auch verbartig: ''오늘 마라탕후루 하자'' (lass uns heute Malatang-Tanghulu machen). Es steht für Teenie-Kultur — bei Erwachsenen klingt es leicht nach Mitmachen.", "en": "Used both for the food pairing and verb-like, as in ''오늘 마라탕후루 하자'' (let''s do malatang-tanghulu today). It signals teen culture, so an adult using it sounds mildly like they''re playing along.", "es": "Se usa para la combinación de comida y también casi como verbo: ''오늘 마라탕후루 하자'' (hoy hacemos malatang-tanghulu). Marca cultura adolescente, así que en boca de un adulto suena a seguirles la corriente.", "ja": "食べ合わせを指すほか、「今日마라탕후루しよう」のように動詞的にも使う。10代の文化を指す語なので、大人が使うと少し合わせにいっている感じが出る。", "vi": "Dùng cho combo món ăn, và cũng như động từ: ''오늘 마라탕후루 하자'' (hôm nay đi malatang-tanghulu đi). Nó gắn với văn hóa tuổi teen nên người lớn dùng nghe hơi kiểu đu theo."}'::jsonb, array['저메추','점메추','인생 맛집'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Malatang-tanghulu (spicy-then-sweet food combo)"}, {"lang": "🇯🇵 JA", "text": "マーラータンフールー(辛い→甘いの定番コース)"}, {"lang": "🇨🇳 ZH", "text": "麻辣烫糖葫芦(先辣后甜的吃法)"}, {"lang": "🇻🇳 VI", "text": "Malatang-tanghulu (combo cay rồi ngọt)"}, {"lang": "🇪🇸 ES", "text": "Malatang-tanghulu (picante y luego dulce)"}, {"lang": "🇩🇪 DE", "text": "Malatang-Tanghulu (scharf, dann süß)"}]'::jsonb),
('456', '자낳괴', 'Ja-Na-Koe', 'new-slang', '돈 앞에서는 체면도 신념도 버리는 사람', '{"de": "Jemand, der für Geld Stolz und Prinzipien fallen lässt", "en": "Someone who drops all pride and principle when money is on the table", "es": "Alguien que tira orgullo y principios cuando hay dinero de por medio", "ja": "金の前では面子も信念も捨てる人", "vi": "Người vứt hết sĩ diện và nguyên tắc khi có tiền"}'::jsonb, '[자나괴]', '[{"type": "명사", "examples": [{"de": "Ein Sponsoring und die Haltung kippt komplett — voll das Kapitalismus-Monster.", "es": "Llega un patrocinio y cambia de actitud al instante. Puro monstruo del capitalismo.", "ja": "広告入った途端に態度が変わったね。完全に資本主義の怪物。", "vi": "Có hợp đồng quảng cáo là đổi thái độ liền. Đúng chuẩn quái vật tư bản.", "eng": "One sponsorship and the whole attitude flips — total capitalism monster.", "kor": "광고 들어오니까 태도 싹 바뀌네. 완전 자낳괴다."}, {"de": "Heute gibt''s Überstundenzuschlag — Kapitalismus-Monster-Modus an.", "es": "Hoy pagan las horas extra, así que activé el modo monstruo del capitalismo.", "ja": "今日残業代出るって言うから資本主義の怪物モード起動した。", "vi": "Nay có phụ cấp tăng ca nên tớ bật chế độ quái vật tư bản.", "eng": "They''re paying overtime today so I switched on capitalism-monster mode.", "kor": "나 오늘 야근수당 준대서 자낳괴 모드 켰다."}], "definition": "''자본주의가 낳은 괴물''을 네 글자로 줄인 말. 돈이 걸리면 사고방식이나 태도를 즉시 바꾸고, 창피한 일도 마다하지 않는 사람을 가리킨다. 진지한 비난보다는 웃으며 놀리는 말로 더 자주 쓴다.", "definition_i18n": {"de": "Kurzform von 자본주의가 낳은 괴물 (''vom Kapitalismus geborenes Monster''). Gemeint ist, wer bei Geld sofort die Haltung wechselt und dafür auch Peinliches tut. Meist lachender Spott, keine ernste Anklage.", "en": "A four-syllable clip of 자본주의가 낳은 괴물 (a monster born of capitalism). It labels someone who flips their attitude the moment money is involved and will do embarrassing things for it. More often a laughing tease than a serious accusation.", "es": "Abreviatura de 자본주의가 낳은 괴물 (''monstruo nacido del capitalismo''). Señala a quien cambia de actitud en cuanto hay dinero y no le importa hacer el ridículo por él. Más burla risueña que acusación seria.", "ja": "「資本主義が生んだ怪物」を4文字に縮めた語。金が絡むと考え方も態度もすぐ変え、恥ずかしいことも厭わない人を指す。真剣な非難というより、笑いながらからかう言い方として使われることが多い。", "vi": "Viết tắt bốn âm của 자본주의가 낳은 괴물 (''quái vật do chủ nghĩa tư bản sinh ra''). Chỉ người hễ dính tới tiền là đổi thái độ ngay, sẵn sàng làm cả chuyện ngượng ngùng. Thường là trêu vui hơn là chê trách nghiêm túc."}}]'::jsonb, '어원은 확정되지 않았다. 가장 널리 인용되는 설은 2010~2011년경 아프리카TV 방송에서 시청자들이 BJ를 두고 ''택진이가 낳은 괴물'', ''별풍선이 낳은 괴물''이라 부르던 드립이 다른 방송으로 퍼지며 ''자본주의가 낳은 괴물''로 굳었다는 것이다. 다만 이 설을 구체적으로 기록한 출처가 한 곳뿐이라 확정하지 않는다.', '{"de": "Die Herkunft ist ungeklärt. Am häufigsten heißt es, um 2010-2011 hätten AfreecaTV-Zuschauer einen Streamer als ''von Taekjin geborenes Monster'' oder ''von Sternballons geboren'' verspottet; beim Weiterwandern wurde daraus ''vom Kapitalismus geborenes Monster''. Nur eine Quelle schildert das im Detail — daher keine Festlegung.", "en": "The etymology is unsettled. The most cited account holds that around 2010-2011 viewers of AfreecaTV streams joked that a streamer was a ''monster born of Taekjin'' or ''born of star balloons'', and as the joke spread it settled into ''monster born of capitalism''. Only one source records this in detail, so it is not stated as fact.", "es": "La etimología no está fijada. La versión más citada dice que hacia 2010-2011 los espectadores de AfreecaTV bromeaban llamando a un streamer ''monstruo nacido de Taekjin'' o ''de los globos estrella'', y al extenderse cuajó como ''monstruo nacido del capitalismo''. Solo una fuente lo detalla, así que no se afirma como hecho.", "ja": "語源は未確定。最も広く引かれる説は、2010〜11年頃アフリカTVの配信で視聴者がBJを「テクジンが生んだ怪物」「星風船が生んだ怪物」とネタにし、それが他の配信に広がる中で「資本主義が生んだ怪物」に定着した、というもの。ただしこの説を詳述する出典は一つだけなので断定しない。", "vi": "Từ nguyên chưa chắc chắn. Cách giải thích hay được dẫn nhất là quanh 2010-2011, khán giả AfreecaTV đùa gọi streamer là ''quái vật do Taekjin sinh ra'' hay ''do bóng sao sinh ra'', rồi khi lan sang kênh khác thì thành ''quái vật do chủ nghĩa tư bản sinh ra''. Chỉ một nguồn ghi chi tiết điều này nên không khẳng định."}'::jsonb, '돈 때문에 태도가 바뀐 사람을 놀릴 때, 또는 ''나 자낳괴야''처럼 스스로를 낮춰 농담할 때 쓴다. 친한 사이의 가벼운 농담이며 처음 보는 사람이나 윗사람에게는 쓰지 않는다.', '{"de": "Um jemanden aufzuziehen, der wegen Geld die Haltung ändert — oder selbstironisch: ''Ich bin ein Kapitalismus-Monster''. Ein lockerer Scherz unter Vertrauten; nicht bei Fremden oder Vorgesetzten.", "en": "Used to tease someone whose attitude changed for money, or self-deprecatingly — ''I''m a total capitalism monster.'' It is a light joke between people who are close; don''t use it on strangers or seniors.", "es": "Para picar a quien cambió de actitud por dinero, o en plan autocrítico: ''soy un monstruo del capitalismo''. Es broma ligera entre gente cercana; no lo uses con desconocidos ni superiores.", "ja": "金のせいで態度が変わった人をからかうとき、または「私、자낳괴だから」と自虐的に使う。親しい間柄の軽い冗談であり、初対面の人や目上には使わない。", "vi": "Dùng để trêu người đổi thái độ vì tiền, hoặc tự giễu: ''tớ là quái vật tư bản mà''. Là câu đùa nhẹ giữa người thân thiết; đừng dùng với người lạ hay bề trên."}'::jsonb, array['흑우','월급루팡','자강두찐'], '{}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Monster born of capitalism (money makes them shameless)"}, {"lang": "🇯🇵 JA", "text": "資本主義が生んだ怪物"}, {"lang": "🇨🇳 ZH", "text": "资本主义养出来的怪物"}, {"lang": "🇻🇳 VI", "text": "Quái vật do chủ nghĩa tư bản sinh ra"}, {"lang": "🇪🇸 ES", "text": "Monstruo nacido del capitalismo"}, {"lang": "🇩🇪 DE", "text": "Vom Kapitalismus geborenes Monster"}]'::jsonb);

commit;

